// JWT 三段结构与 base64url 编解码（Node 内置 Buffer，零第三方依赖）
const HEADER = { alg: 'HS256', typ: 'JWT' };
const PAYLOAD = { sub: '1001', name: 'alice', role: 'admin', iat: 1700000000 };

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function b64urlDecodeToBuffer(s) {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + pad;
  return Buffer.from(b64, 'base64');
}
function b64urlDecodeToString(s) { return b64urlDecodeToBuffer(s).toString('utf8'); }

const h = b64urlEncode(JSON.stringify(HEADER));
const p = b64urlEncode(JSON.stringify(PAYLOAD));

console.log('header_segment=' + h);
console.log('payload_segment=' + p);
console.log('token_segments=' + (h + '.' + p + '.SIG').split('.').length);
console.log('padding_present=' + /=/.test(h + p));
console.log('decoded_header=' + b64urlDecodeToString(h));
console.log('decoded_payload=' + b64urlDecodeToString(p));
console.log('payload_sub=' + JSON.parse(b64urlDecodeToString(p)).sub);
console.log('roundtrip_ok=' + (b64urlDecodeToString(p) === JSON.stringify(PAYLOAD)));

// 标准 base64 与 base64url 的字符集差异（+ / 与 - _）
const raw = Buffer.from([251, 255, 62]);
console.log('std_base64=' + raw.toString('base64'));
console.log('url_base64=' + b64urlEncode(raw));
console.log('charset_differs=' + (raw.toString('base64') !== b64urlEncode(raw)));

// base64 是编码不是加密：任何人都能解开 payload
console.log('payload_is_readable_by_anyone=' + (JSON.parse(b64urlDecodeToString(p)).role === 'admin'));
